  {auto noSuppression=planNativeStreamPrimaryProfile(fixture(),targets());const auto restored=parseNativeStreamProfilePayload(nativeStreamProfilePayloadBytes(noSuppression));require(!restored.suppressedConsole&&nativeStreamProfileSignatures(restored.applied)==nativeStreamProfileSignatures(noSuppression.applied),"Translate-only payload changed semantics");++cases;}
  {auto different=fixture();for(auto& path:different.paths){path.targetInfo.refreshRate={60000,1001};different.modes[nativeTargetIndex(path)].targetMode.targetVideoSignalInfo.vSyncFreq={75,1};}different.paths[3].targetInfo.rotation=DISPLAYCONFIG_ROTATION_ROTATE180;different.paths[3].targetInfo.scaling=DISPLAYCONFIG_SCALING_CENTERED;const auto p=planNativeStreamPrimaryProfile(different,targets(),consoleKey());const auto output=parseNativeStreamProfilePayload(nativeStreamProfilePayloadBytes(p));require(nativeStreamProfileSignatures(p.before)==nativeStreamProfileSignatures(output.before),"Codec imposed60fps or identity scaling/rotation");++cases;}
  {auto cloned=fixture();addPath(cloned,adapter(88),0,5,800,600,-800,0,false,nativeSourceIndex(cloned.paths.back()));const auto p=planNativeStreamPrimaryProfile(cloned,targets(),consoleKey());const auto output=parseNativeStreamProfilePayload(nativeStreamProfilePayloadBytes(p));require(output.before.modes.size()==p.before.modes.size()&&nativeStreamProfileSignatures(p.before)==nativeStreamProfileSignatures(output.before),"Foreign clone mode sharing lost");++cases;}
  {auto desktop=fixture();desktop.modes[desktop.paths[0].targetInfo.desktopModeInfoIdx].adapterId.LowPart=UINT32_MAX;desktop.modes[desktop.paths[0].targetInfo.desktopModeInfoIdx].id=UINT32_MAX;const auto p=planNativeStreamPrimaryProfile(desktop,targets(),consoleKey());require(nativeStreamProfileSignatures(parseNativeStreamProfilePayload(nativeStreamProfilePayloadBytes(p)).before)==nativeStreamProfileSignatures(p.before),"Desktop image unsigned identity lost in canonical signed row");++cases;}
