  rejects([&]{parseNativeStreamProfilePayload(" "+bytes);},"Noncanonical whitespace accepted");
  {auto value=JsonParser::parse(bytes);object(value)["extra"].value=true;rejects([&]{parseNativeStreamProfilePayload(value);},"Extra root field accepted");}
  {auto value=JsonParser::parse(bytes);object(value).erase("suppressedConsole");object(value)["other"].value=nullptr;rejects([&]{parseNativeStreamProfilePayload(value);},"Missing nullable required field accepted");}
  {auto value=JsonParser::parse(bytes);object(value)["schema"].value=2.0;rejects([&]{parseNativeStreamProfilePayload(value);},"Unknown schema accepted");}
  {auto value=JsonParser::parse(bytes);object(value)["schema"].value=std::string("1");rejects([&]{parseNativeStreamProfilePayload(value);},"String schema accepted");}
  {auto value=JsonParser::parse(bytes);object(array(object(value)["targets"])[0])["width"].value=1921.0;rejects([&]{parseNativeStreamProfilePayload(value);},"Odd owned size accepted");}
  {auto value=JsonParser::parse(bytes);object(array(object(value)["targets"])[0])["target"].value=100.5;rejects([&]{parseNativeStreamProfilePayload(value);},"Fractional target ID accepted");}
  {auto value=JsonParser::parse(bytes);object(array(object(value)["targets"])[0])["id"].value=std::string("2");rejects([&]{parseNativeStreamProfilePayload(value);},"Noncanonical owned ID accepted");}
  {auto value=JsonParser::parse(bytes);object(object(value)["suppressedConsole"])["target"].value=100.0;rejects([&]{parseNativeStreamProfilePayload(value);},"Wrong exact console key accepted");}
  for(const auto index:{size_t(6),size_t(7),size_t(14),size_t(19),size_t(30),size_t(46)}){auto value=JsonParser::parse(bytes);array(array(object(value)["paths"])[0])[index].value=std::string("999999999999999999999999");rejects([&]{parseNativeStreamProfilePayload(value);},"Out of range path field accepted");}
  {auto value=JsonParser::parse(bytes);array(array(object(value)["paths"])[0])[1].value=77.0;rejects([&]{parseNativeStreamProfilePayload(value);},"Numeric field bypassed exact canonical integer string");}
