struct Backend {
  NativeStreamPrimaryProfile saved=profile();NativeCcdData current=saved.before;bool eligible=true,identity=true,prepareAck=true,completeAck=true,applyChanges=true;
  LONG validateError=ERROR_SUCCESS,applyError=ERROR_SUCCESS;uint64_t tick=100;int queries=0,validations=0,applications=0,prepares=0,completions=0,identityChecks=0;
  std::function<void(int)> onQuery;std::function<void()> onPrepare,onValidate,onApply,onComplete,onIdentity;std::vector<std::string> events;
  NativeCcdData query(){++queries;events.push_back("query");if(onQuery)onQuery(queries);auto value=current;
    if(saved.suppressedConsole&&std::none_of(value.paths.begin(),value.paths.end(),[&](const auto& p){return nativeStreamConsolePathMatches(p,*saved.suppressedConsole);})){auto inactive=saved.before.paths.front();inactive.flags&=~DISPLAYCONFIG_PATH_ACTIVE;inactive.sourceInfo.modeInfoIdx=DISPLAYCONFIG_PATH_MODE_IDX_INVALID;inactive.targetInfo.modeInfoIdx=DISPLAYCONFIG_PATH_MODE_IDX_INVALID;value.paths.push_back(inactive);}return value;
  }
  NativeStreamProfileTransactionAccess access(){
    NativeStreamProfileTransactionAccess a;
    a.topology.query=[&]{return query();};a.topology.configure=[&](const NativeCcdData& desired,UINT32 flags)->LONG{
      require(!(flags&(SDC_SAVE_TO_DATABASE|SDC_ALLOW_CHANGES|SDC_ALLOW_PATH_ORDER_CHANGES)),"Coordinator weakened supplied configuration requirements");
      if(flags&SDC_VALIDATE){++validations;events.push_back("validate");if(onValidate)onValidate();return validateError;}
      require(bool(flags&SDC_APPLY),"Unexpected configure command");++applications;events.push_back("apply");if(applyChanges)current=desired;if(onApply)onApply();return applyError;
    };a.topology.eligible=[&]{return eligible;};a.topology.now=[&]{return tick;};a.topology.pause=[&]{tick+=50;};
    a.identityCurrent=[&]{++identityChecks;if(onIdentity)onIdentity();return identity;};
    a.durablePrepared=[&](const NativeCcdData& before,const NativeCcdData& requested){++prepares;events.push_back("prepared");require(nativeStreamProfileSignatures(before)==nativeStreamProfileSignatures(current),"Prepared journal did not receive fresh before topology");require(!requested.paths.empty(),"Prepared journal missing desired proof");if(onPrepare)onPrepare();return prepareAck;};
    a.durableComplete=[&](const NativeCcdData& observed){++completions;events.push_back("completed");require(nativeStreamProfileSignatures(observed)==nativeStreamProfileSignatures(current),"Completion used stale proof");if(onComplete)onComplete();return completeAck;};return a;
  }
};
