  {Backend b;b.onPrepare=[] {throw std::runtime_error("lost prepare ack");};const auto r=enterNativeStreamPrimaryProfile(b.saved,b.access());require(!r.ok&&r.prepareAttempted&&!r.preparedAcknowledged&&!r.applyAttempted&&r.recoveryRequired,"Thrown prepare ACK loss was treated as no pending journal");++cases;}
