  {Backend b;b.onValidate=[&]{b.current.modes[nativeSourceIndex(b.current.paths.back())].sourceMode.position.y+=2;};const auto r=enterNativeStreamPrimaryProfile(b.saved,b.access());require(!r.ok&&!r.applyAttempted&&b.applications==0,"Foreign edit between VALIDATE and APPLY overwritten");++cases;}
